 summary:[{"id":"s1","title":"Visão geral da comunicação processual","match":"1. VISÃO GERAL DA COMUNICAÇÃO PROCESSUAL"},{"id":"s2","title":"Cartas","match":"2. CARTAS - ARTS. 236, 237 E 260 A 268"},{"id":"s3","title":"Citação: conceito, validade e comparecimento espontâneo","match":"3. CITAÇÃO - CONCEITO, VALIDADE E COMPARECIMENTO"},{"id":"s4","title":"Efeitos da citação","match":"4. EFEITOS DA CITAÇÃO - ART. 240"},{"id":"s5","title":"Quem recebe, onde e quando","match":"5. QUEM RECEBE, ONDE E QUANDO"},{"id":"s6","title":"Formas de citação","match":"6. FORMAS DE CITAÇÃO"},{"id":"s7","title":"Intimação","match":"7. INTIMAÇÃO - ARTS. 269 A 275"},{"id":"s8","title":"Nulidades processuais","match":"8. NULIDADES PROCESSUAIS - ARTS. 276 A 283"},{"id":"s9","title":"Nulidade absoluta, relativa, irregularidade e ineficácia","match":"9. NULIDADE ABSOLUTA, RELATIVA, IRREGULARIDADE E"},{"id":"s10","title":"Números para decorar","match":"10. NÚMEROS PARA DECORAR"},{"id":"s11","title":"Jurisprudência e atualizações 2024-2026","match":"11. JURISPRUDÊNCIA E ATUALIZAÇÕES 2024-2026"},{"id":"s12","title":"Pegadinhas FCC","match":"12. PEGADINHAS FCC"},{"id":"s13","title":"Teste rápido — padrão FCC","match":"13. TESTE RÁPIDO - PADRÃO FCC"},{"id":"s14","title":"Revisão de véspera","match":"14. REVISÃO DE VÉSPERA"},{"id":"s15","title":"Checklist de domínio","match":"15. CHECKLIST DE DOMÍNIO"}],
 complete:[{"id":"c1","title":"Visão geral","match":"1. VISÃO GERAL"},{"id":"c2","title":"Cartas","match":"2. CARTAS — CPC, ARTS. 236, 237 E 260 A 268"},{"id":"c3","title":"Citação","match":"3. CITAÇÃO"},{"id":"c4","title":"Efeitos da citação","match":"4. EFEITOS DA CITAÇÃO — ART. 240"},{"id":"c5","title":"Quem pode receber, onde e quando","match":"5. QUEM PODE RECEBER, ONDE E QUANDO"},{"id":"c6","title":"Formas de citação","match":"6. FORMAS DE CITAÇÃO"},{"id":"c7","title":"Intimação","match":"7. INTIMAÇÃO — ARTS. 269 A 275"},{"id":"c8","title":"Nulidades processuais","match":"8. NULIDADES PROCESSUAIS — ARTS. 276 A 283"},{"id":"c9","title":"Nulidade absoluta, relativa, irregularidade e ineficácia","match":"9. NULIDADE ABSOLUTA, RELATIVA, IRREGULARIDADE E"},{"id":"c10","title":"Quadro de prazos e números","match":"10. QUADRO DE PRAZOS E NÚMEROS PARA DECORAR"},{"id":"c11","title":"Jurisprudência e atualizações 2024-2026","match":"11. JURISPRUDÊNCIA E ATUALIZAÇÕES 2024–2026 QUE"},{"id":"c12","title":"Pegadinhas de prova","match":"12. PEGADINHAS DE PROVA"},{"id":"c13","title":"Teste rápido — padrão FCC","match":"13. TESTE RÁPIDO — PADRÃO FCC"},{"id":"c14","title":"Decore final","match":"14. DECORE FINAL"},{"id":"c15","title":"Fontes de controle da versão final","match":"15. FONTES DE CONTROLE DA VERSÃO FINAL"}]
